// A fixture for .github/tools/src/scripts/release-notes.ts: a fake `gh` that serves one release from disk and logs every call,
// and a runner that starts the real adapter with it first on PATH.

import { spawnSync } from "node:child_process";
import {
  chmodSync,
  copyFileSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
} from "node:fs";
import { delimiter, dirname, join } from "node:path";
import { repoRoot } from "./repo.ts";
import { scratchDir } from "./support.ts";

export const TARGET_SHA = "0123456789abcdef0123456789abcdef01234567";

// What footerLine() builds from the fixture's env: GITHUB_SERVER_URL, GH_REPO, GITHUB_RUN_ID, NOTES_ENGINE and
// NOTES_MODEL.
export const FOOTER =
  "> Generated by [Agentics release](https://github.com/muehz/agentics/actions/runs/7) · copilot · gpt-5.6-luna?effort=high";

// The fake gh. It answers `gh api repos/muehz/agentics/releases/42` from state/release.json, applies a PATCH of exactly
// {body}, and appends each call to the log. FAKE_GH_PATCH_FAIL, FAKE_GH_FLIP_ON_PATCH and FAKE_GH_REREAD_FAIL make it
// misbehave. String.raw keeps the backslash escapes of the script's own string literals.
export const FAKE_GH = String.raw`#!/usr/bin/env node
const fs = require("fs");
const path = require("path");

const state = process.env.FAKE_GH_STATE;
const log = process.env.FAKE_GH_LOG;
const args = process.argv.slice(2);
if (process.platform === "win32") args.unshift(path.basename(process.argv[1]));
const stdin = fs.readFileSync(0, "utf8");
const append = (value) => fs.appendFileSync(log, JSON.stringify(value) + "\n");
append({args, input: stdin});

if (args[0] !== "api") {
  process.stderr.write("fake gh rejected non-api command\n");
  process.exit(97);
}
const endpoint = args.find((arg) => arg.startsWith("repos/"));
if (!endpoint || endpoint !== "repos/muehz/agentics/releases/42") {
  process.stderr.write("fake gh rejected endpoint\n");
  process.exit(97);
}
const releasePath = path.join(state, "release.json");
const release = JSON.parse(fs.readFileSync(releasePath, "utf8"));
if (args.includes("PATCH")) {
  if (process.env.FAKE_GH_PATCH_FAIL === "1") {
    process.stderr.write("fake patch failed\n");
    process.exit(4);
  }
  const payload = JSON.parse(stdin);
  if (Object.keys(payload).length !== 1 || typeof payload.body !== "string") {
    process.stderr.write("fake gh rejected patch payload\n");
    process.exit(97);
  }
  release.body = payload.body;
  if (process.env.FAKE_GH_FLIP_ON_PATCH === "1") release.prerelease = !release.prerelease;
  fs.writeFileSync(releasePath, JSON.stringify(release));
  process.stdout.write(JSON.stringify(release));
  process.exit(0);
}
const countPath = path.join(state, "get-count");
const count = Number(fs.existsSync(countPath) ? fs.readFileSync(countPath, "utf8") : "0") + 1;
fs.writeFileSync(countPath, String(count));
if (process.env.FAKE_GH_REREAD_FAIL === "1" && count > 1) {
  process.stderr.write("fake reread failed\n");
  process.exit(5);
}
process.stdout.write(JSON.stringify(release));
`;

export interface NotesRelease {
  id: number;
  tag_name: string;
  name: string;
  prerelease: boolean;
  draft: boolean;
  target_commitish: string;
  body: string;
}

export interface GhCall {
  readonly args: readonly string[];
  readonly input: string;
}

export interface NotesFixture {
  release: NotesRelease;
  readonly env: Record<string, string | undefined>;
  useState(overrides?: Record<string, unknown>): string;
  writeRelease(): void;
  readRelease(): NotesRelease;
  run(...items: Record<string, unknown>[]): {
    status: number | null;
    output: string;
  };
  calls(): GhCall[];
}

// Windows needs a native gh.exe. A copy of Node executes "api" from its working directory,
// passing the remaining gh arguments and stdin to the same fixture as the POSIX executable.
const bin = scratchDir("agentics-notes-bin-");
if (process.platform === "win32") {
  copyFileSync(process.execPath, join(bin, "gh.exe"));
  writeFileSync(join(bin, "api"), FAKE_GH);
} else {
  const executable = join(bin, "gh");
  writeFileSync(executable, FAKE_GH);
  chmodSync(executable, 0o755);
}

export function newNotesAdapterFixture(): NotesFixture {
  const root = scratchDir("agentics-notes-");
  const state = join(root, "state");
  const ghLog = join(root, "gh.log");
  const baseline = join(root, "baseline.md");
  const agentOutput = join(root, "agent-output.json");
  const script = join(
    repoRoot,
    ".github",
    "tools",
    "src",
    "scripts",
    "release-notes.ts",
  );
  mkdirSync(state, { recursive: true });
  writeFileSync(ghLog, "");
  writeFileSync(baseline, "BASELINE NOTES\n");

  const fixture: NotesFixture = {
    release: {
      id: 42,
      tag_name: "v1.86.0",
      name: "v1.86.0",
      target_commitish: TARGET_SHA,
      draft: false,
      prerelease: true,
      body: "BASELINE NOTES\n",
    },
    env: {
      RELEASE_ID: "42",
      TARGET_SHA,
      TAG: "v1.86.0",
      GH_REPO: "muehz/agentics",
      BASELINE_NOTES: baseline,
      GITHUB_SERVER_URL: "https://github.com",
      GITHUB_RUN_ID: "7",
      NOTES_ENGINE: "copilot",
      NOTES_MODEL: "gpt-5.6-luna?effort=high",
      RELEASE_PRERELEASE: "true",
    },
    useState(overrides) {
      const path = join(root, "state.json");
      writeFileSync(
        path,
        JSON.stringify({
          sha: TARGET_SHA,
          tag: "v1.86.0",
          release_id: "42",
          prerelease: true,
          ...overrides,
        }),
      );
      fixture.env["RELEASE_STATE_FILE"] = path;
      return path;
    },
    writeRelease() {
      writeFileSync(
        join(state, "release.json"),
        JSON.stringify(fixture.release),
      );
    },
    readRelease() {
      return JSON.parse(
        readFileSync(join(state, "release.json"), "utf8"),
      ) as NotesRelease;
    },
    run(...items) {
      writeFileSync(agentOutput, JSON.stringify({ items }));
      const env = {
        ...fixture.env,
        SystemRoot: process.env.SystemRoot,
        PATH: [bin, dirname(process.execPath)].join(delimiter),
        FAKE_GH_STATE: state,
        FAKE_GH_LOG: ghLog,
        GH_AW_AGENT_OUTPUT: agentOutput,
      };
      const result = spawnSync(process.execPath, [script], {
        cwd: bin,
        env,
        encoding: "utf8",
      });
      return {
        status: result.status,
        output: `${result.stdout}${result.stderr}`,
      };
    },
    calls() {
      const text = readFileSync(ghLog, "utf8").trim();
      if (text === "") return [];
      return text.split("\n").map((line) => JSON.parse(line) as GhCall);
    },
  };
  fixture.writeRelease();
  return fixture;
}
